ALTER TABLE "SocialInsuranceRecord" ADD COLUMN "coverageCohort" TEXT, ADD COLUMN "firstCoverageDate" TIMESTAMP(3);
ALTER TABLE "PayrollItem" ADD COLUMN "calculationSnapshot" JSONB, ADD COLUMN "employerInsurance" DECIMAL(12,2) NOT NULL DEFAULT 0;
CREATE TABLE "gosi_settings" ("id" TEXT PRIMARY KEY, "cohort" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "employeeRate" DECIMAL(5,2) NOT NULL, "employerRate" DECIMAL(5,2) NOT NULL, "minimumWage" DECIMAL(12,2) NOT NULL, "maximumWage" DECIMAL(12,2) NOT NULL, "housingIncluded" BOOLEAN NOT NULL DEFAULT true, "newSystemCutoff" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "gosi_policy_range" CHECK ("employeeRate" BETWEEN 0 AND 100 AND "employerRate" BETWEEN 0 AND 100 AND "minimumWage" >= 0 AND "maximumWage" >= "minimumWage" AND ("effectiveTo" IS NULL OR "effectiveTo" >= "effectiveFrom")));
CREATE UNIQUE INDEX "gosi_settings_cohort_effectiveFrom_key" ON "gosi_settings"("cohort", "effectiveFrom");
CREATE TABLE "salary_rules" ("id" TEXT PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "OdooPayrollSnapshot" ("id" TEXT PRIMARY KEY, "source" TEXT NOT NULL, "odooPayslipId" INTEGER NOT NULL, "employeeId" TEXT NOT NULL, "state" TEXT NOT NULL, "period" TEXT NOT NULL, "currency" TEXT NOT NULL, "moveId" INTEGER, "raw" JSONB NOT NULL, "lines" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "OdooPayrollSnapshot_source_odooPayslipId_key" ON "OdooPayrollSnapshot"("source", "odooPayslipId");
CREATE INDEX "OdooPayrollSnapshot_employeeId_period_idx" ON "OdooPayrollSnapshot"("employeeId", "period");
CREATE TABLE "PayrollAccountingOutbox" ("id" TEXT PRIMARY KEY, "payrollRunId" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
